// A desktop from 2000 around the scene it wraps: the scene in a window with a
// yellow tab, the Deskbar in the top right corner and a few icons under it. The
// Deskbar's gem opens the scene list, its tray (signal, battery, clock) the frame's
// page, and below them the running scene puts its window away and brings it back,
// and Settings opens its settings. The tab's close box closes the scene to the
// list, its zoom box fills the desktop with the window and back, and a double tap
// on the tab hides the window. On a narrow panel the Deskbar runs along the top,
// with no room for the icons. Built-in scenes are drawn in the window too.
//
// On a frame that runs its scenes side by side (a Raspberry Pi: app.frame.scenes
// is there), it is a desktop: every scene opened is a window, and they all run at
// once, and chosen in another desktop's place (the frame page's Layout), it opens what
// that one had open. A window opens at the layout's "Window size" (800x480, a 7.5-inch frame's,
// unless it says otherwise), filling the desktop beside the Deskbar where that does
// not fit, and where it was when its scene opens again. The scene with the focus is
// the frame's own (the <yield />, its tab yellow), the others are <Scene>s (their
// tabs grey). Drag a tab to move a window and its frame to size it, a double click
// on the tab puts it away, the zoom box fills the desktop with it, and let go at
// the top edge it fills it, at a side it takes that half. The Deskbar lists the
// windows open (a click brings one forward, or puts the one in front away), its gem
// opens the Be menu (the frame's scenes, the scene store and the asset browser
// where the frame has them, Preferences, Terminal), and the icons under it (a
// double click) the frame's own apps: Frame (Preferences), Scenes (the scene
// list), those two and Terminal. F11 or the Be
// menu's "Full screen" gives the panel to the window in front (Escape takes it
// back, and the pointer at the top edge brings the Deskbar). Alt+Tab goes between
// windows, Alt+W closes the one in front. The gear box on a scene's tab opens its
// settings ("Clock Settings", a window a scene, several open at once); the frame's
// own scenes open in windows of their own over the scene, stay open while another
// window has the focus, and close when they go back by themselves (Save, Cancel, a
// scene picked).
const pad = (n) => String(n).padStart(2, '0')
const on = (value) => value === true || value === 'true'

// The frame's own scenes (the contract's `scenes.settings`, `scenes.switcher` and
// `scenes.terminal`), and the command that opens each, which also sends it back.
const SETTINGS = 'system/sceneSettings'
// On a desktop every scene's settings are a scene of their own, this and the
// scene's id (the contract's `scenes.settingsWindow`); the plain id is the frame's
// page, Preferences.
const SETTINGS_OF = 'system/sceneSettings#'
const settingsOf = (id) => SETTINGS_OF + id
const settingsFor = (id) => (typeof id === 'string' && id.startsWith(SETTINGS_OF) ? id.slice(SETTINGS_OF.length) : null)
const SWITCHER = 'system/sceneSwitcher'
const TERMINAL = 'system/terminal'
const commandOf = (id) => (id === SWITCHER ? 'sceneSwitcher' : id === TERMINAL ? 'terminal' : 'sceneSettings')
const isSystem = (id) => typeof id === 'string' && id.startsWith('system/')
// The frame's own apps that are scenes like any other, which the frame may have
// (docs/scene-store.md): the scene store and the asset browser, by their sample's
// id, or by their name where a control plane gave them another id. A desktop has
// entries of its own for them, and leaves them out of its scene lists.
const appIs = (id, name) => (scene) =>
  !!scene && (scene.id === id || String(scene.name || '').trim().toLowerCase() === name)
const isStore = appIs('scene-store', 'scene store')
const isAssets = appIs('asset-browser', 'asset browser')
const isFrameApp = (scene) => isStore(scene) || isAssets(scene)
const findScene = (app, test) => (Array.isArray(app.frame.scenes) ? app.frame.scenes.find(test) : undefined)
const storeOf = (app) => findScene(app, isStore)
const assetsOf = (app) => findScene(app, isAssets)
const BAG = 'M6 7V6a6 6 0 0 1 12 0v1h2.5l-1 15h-15l-1-15ZM8 7h8V6a4 4 0 0 0-8 0Z'

// ------------------------------------------------------------ the frame's pages
//
// The frame's own pages (a scene's settings, the frame's, the scene list, the
// terminal, the keyboard on the screen) in this layout's look: a theme is each
// kind of element's classes (docs/jsx-ui.md "Themes"), a string for one box or a
// list for boxes inside each other (a bevel is two or three, as a box has one
// border color). The layout keeps it in its state as `theme`, where the frame
// reads it; not on an ESP32, where the pages keep their own look, nor on e-paper
// but for high contrast.
const CONTRAST = {
  page: 'bg-black text-white',
  bar: 'border-b-2 border-white',
  button: 'font-bold bg-black text-white border-2 border-white active:bg-white active:text-black',
  primary: 'font-bold bg-white text-black border-2 border-white active:bg-black active:text-white',
  selected: 'bg-white text-black border-2 border-white',
  field: 'bg-black text-white border-2 border-white placeholder:text-white focus:border-[#ffff00]',
  option: 'active:bg-white active:text-black',
  picked: 'bg-white text-black',
  switch: 'rounded-full border-2 border-white',
  switchOn: 'rounded-full bg-white border-2 border-white',
  knob: 'rounded-full bg-white',
  knobOn: 'rounded-full bg-black',
  muted: 'text-white',
  card: 'border-2 border-white',
  tile: 'bg-black text-white border-2 border-white active:bg-white active:text-black',
  tileLit: 'bg-black text-white border-4 border-[#ffff00]',
  accent: 'bg-[#ffff00]',
  keyboard: 'bg-black text-white border-t-2 border-white',
  key: 'bg-black text-white border-2 border-white active:bg-white active:text-black',
  keyMod: 'bg-black text-[#ffff00] border-2 border-white active:bg-white active:text-black',
  keyLit: 'bg-white text-black border-2 border-white',
  terminal: 'bg-black text-white',
  prompt: 'font-bold text-[#ffff00]',
}

function dress(app, themes, fallback) {
  if (app.frame.embedded) return
  const name = String(app.state.look || fallback)
  const theme = name === 'contrast' ? CONTRAST : app.frame.paper ? null : themes[name] || null
  const key = theme ? name : ''
  if ((app.state.themeOf || '') === key) return
  frameos.setState('theme', theme)
  frameos.setState('themeOf', key)
}

// A button: a dark outline, lit along its top and left inside it.
const BUTTON = ['rounded-[4px] border-1 border-[#6c6c6c] bg-[#e8e8e8] active:bg-[#b8b8b8]', 'rounded-[3px] border-t-1 border-l-1 border-white']
const SUNK = ['border-t-1 border-l-1 border-[#989898]', 'border-b-1 border-r-1 border-white']
const THEMES = {
  beos: {
    page: 'bg-[#d8d8d8] text-black',
    bar: 'border-b-1 border-[#989898]',
    button: BUTTON,
    primary: ['rounded-[5px] border-2 border-black bg-[#e8e8e8] active:bg-[#b8b8b8]', 'rounded-[3px] border-t-1 border-l-1 border-white'],
    selected: ['rounded-[4px] border-1 border-[#6c6c6c] bg-[#b8b8b8]', 'rounded-[3px] border-b-1 border-r-1 border-white'],
    field: [SUNK[0], 'bg-white text-black border-b-1 border-r-1 border-white placeholder:text-[#989898]'],
    option: 'active:bg-[#989898]',
    picked: 'bg-[#336698] text-white',
    switch: [...SUNK, 'bg-white'],
    switchOn: [...SUNK, 'bg-[#336698]'],
    knob: ['bg-[#d8d8d8] border-1 border-[#6c6c6c]', 'border-t-1 border-l-1 border-white'],
    knobOn: ['bg-[#d8d8d8] border-1 border-[#6c6c6c]', 'border-t-1 border-l-1 border-white'],
    muted: 'text-[#505050]',
    card: SUNK,
    tile: ['border-1 border-[#6c6c6c] bg-[#e8e8e8] active:bg-[#b8b8b8]', 'border-t-1 border-l-1 border-white'],
    tileLit: ['border-2 border-[#ffcb00] bg-[#e8e8e8]', 'border-t-1 border-l-1 border-white'],
    accent: 'bg-[#ffcb00]',
    keyboard: 'bg-[#d8d8d8] text-black border-t-1 border-[#989898]',
    key: BUTTON,
    keyMod: ['rounded-[4px] border-1 border-[#6c6c6c] bg-[#c8c8c8] active:bg-[#b8b8b8]', 'rounded-[3px] border-t-1 border-l-1 border-white'],
    keyLit: ['rounded-[4px] border-1 border-[#6c6c6c] bg-[#ffcb00]', 'rounded-[3px] border-t-1 border-l-1 border-[#fff0a0]'],
    terminal: 'bg-white text-black',
    prompt: 'font-bold',
  },
}

// Sizes are pixels of the desktop's own: twice that from a short side of 2160 (a 4K
// screen), or of 1000 on e-paper, whose pixels are small, and in proportion under
// 480, which has no room for them. The frame's render scale multiplies on top.
let zoom = 1
let edge = 1 // the bevels' width
const px = (n) => `${Math.round(n * zoom * 10) / 10}px`

function clock(now, twentyFour) {
  const minutes = pad(now.getMinutes())
  if (twentyFour) return `${pad(now.getHours())}:${minutes}`
  return `${now.getHours() % 12 || 12}:${minutes} ${now.getHours() < 12 ? 'AM' : 'PM'}`
}

// The colors of the time. On e-paper the light grey is white, as a dithered grey
// is a field of dots there, and the bevels' shade is black. A window behind has a
// grey tab.
const R5 = {
  desk: 'bg-[#336698]',
  panel: '#d8d8d8',
  pressed: '#b8b8b8',
  light: '#ffffff',
  shade: '#989898',
  line: '#6c6c6c',
  tab: '#ffcb00',
  tabLight: '#fff0a0',
  tabShade: '#c49600',
  idleTab: '#e0e0e0',
  idleShade: '#a0a0a0',
  boxes: ['#fffbe2', '#f0b400'],
  idleBoxes: ['#ffffff', '#c4c4c4'],
  pick: 'hover:bg-[#9a9a9a]',
}
const PAPER = {
  ...R5,
  panel: '#ffffff',
  pressed: '#ffffff',
  shade: '#000000',
  line: '#000000',
  tabShade: '#000000',
  idleTab: '#ffffff',
  idleShade: '#000000',
  idleBoxes: ['#ffffff', '#ffffff'],
  pick: 'hover:bg-black hover:text-white',
}
const MONO = { ...R5, desk: 'bg-[#4a4a4a]', line: '#000000', shade: '#7a7a7a', pick: 'hover:bg-black hover:text-white' }
let c = R5

// A box has one border color, so a bevel is two boxes inside each other: light
// at the top and the left, shade at the bottom and the right. Pressed, they swap.
const Bevel = ({ pressed = false, className = '', inner = '', onClick, children }) => (
  <div
    className={`flex border-t-${edge} border-l-${edge} border-[${pressed ? c.shade : c.light}] ${className}`}
    onClick={onClick}
  >
    <div
      className={`flex flex-1 min-w-0 min-h-0 border-b-${edge} border-r-${edge} border-[${pressed ? c.light : c.shade}] ${
        pressed ? `bg-[${c.pressed}]` : `bg-[${c.panel}] active:bg-[${c.pressed}]`
      } ${inner}`}
    >
      {children}
    </div>
  </div>
)

// The Deskbar's menu: a cut gem.
const Gem = () => (
  <svg viewBox="0 0 24 20" className={`w-[${px(28)}] h-[${px(23)}]`}>
    <path d="M6 1H18L23 7L12 19L1 7Z" fill="#3a78d8" />
    <path d="M8 1H16L18 7H6Z" fill="#b4d8ff" />
    <path d="M6 1H8L6 7H1Z" fill="#78b2f6" />
    <path d="M16 1H18L23 7H18Z" fill="#2c66c4" />
    <path d="M1 7H6L12 19Z" fill="#2858ab" />
    <path d="M6 7H18L12 19Z" fill="#4f92ea" />
    <path d="M18 7H23L12 19Z" fill="#1c4690" />
    <path d="M6 1H18L23 7L12 19L1 7Z" fill="none" stroke="#0f2a5e" strokeWidth="0.9" strokeLinejoin="round" />
    <path d="M19.5 0.5L20.2 2.3L22 3L20.2 3.7L19.5 5.5L18.8 3.7L17 3L18.8 2.3Z" fill="#ffffff" />
  </svg>
)

// The open scene in the Deskbar: a window of its own, yellow tab and all.
const SceneGlyph = () => (
  <svg viewBox="0 0 16 16" className={`w-[${px(16)}] h-[${px(16)}] shrink-0`}>
    <rect x="0.5" y="0.5" width="9" height="4" fill="#ffcb00" stroke="#000000" />
    <rect x="0.5" y="4.5" width="15" height="11" fill="#d8d8d8" stroke="#000000" />
    <rect x="2.5" y="6.5" width="11" height="7" fill="#336698" stroke="#6c6c6c" />
  </svg>
)

const GEAR = 'M7 0.5H9L9.4 2.6L10.9 3.2L12.6 1.9L14.1 3.4L12.8 5.1L13.4 6.6L15.5 7V9L13.4 9.4L12.8 10.9L14.1 12.6L12.6 14.1L10.9 12.8L9.4 13.4L9 15.5H7L6.6 13.4L5.1 12.8L3.4 14.1L1.9 12.6L3.2 10.9L2.6 9.4L0.5 9V7L2.6 6.6L3.2 5.1L1.9 3.4L3.4 1.9L5.1 3.2L6.6 2.6ZM10.5 8A2.5 2.5 0 1 0 5.5 8A2.5 2.5 0 1 0 10.5 8Z'

const SettingsGlyph = () => (
  <svg viewBox="0 0 16 16" className={`w-[${px(16)}] h-[${px(16)}] shrink-0`}>
    <path d={GEAR} fill="#9a9a9a" stroke="#000000" strokeWidth="0.8" strokeLinejoin="round" />
  </svg>
)

// The terminal: a prompt on a black screen.
const TerminalGlyph = ({ size = 16 }) => (
  <svg viewBox="0 0 16 16" className={`w-[${px(size)}] h-[${px(size)}] shrink-0`}>
    <rect x="0.5" y="1.5" width="15" height="13" fill="#000000" stroke="#6c6c6c" />
    <path fill="none" stroke="#30e060" strokeWidth="1.4" d="M3 5L6 8L3 11M7.5 11.5H12" />
  </svg>
)

// The scene store: a shopping bag.
const StoreGlyph = ({ size = 16 }) => (
  <svg viewBox="0 0 24 24" className={`w-[${px(size)}] h-[${px(size)}] shrink-0`}>
    <path d={BAG} fill="#ffcb00" stroke="#000000" strokeWidth="1.3" strokeLinejoin="round" />
  </svg>
)

// The asset browser: a picture.
const PictureGlyph = ({ size = 16 }) => (
  <svg viewBox="0 0 16 16" className={`w-[${px(size)}] h-[${px(size)}] shrink-0`}>
    <rect x="0.5" y="2.5" width="15" height="11" fill="#87ceeb" stroke="#000000" />
    <path fill="#2e8b57" d="M1 13L6 7L9.5 10.5L11.5 8.5L15 13Z" />
    <circle cx="11.5" cy="5.5" r="1.4" fill="#ffd700" />
  </svg>
)

let storeId = null
let assetsId = null
const glyphOf = (id) =>
  id === TERMINAL ? (
    <TerminalGlyph />
  ) : isSystem(id) ? (
    <SettingsGlyph />
  ) : id === storeId ? (
    <StoreGlyph />
  ) : id === assetsId ? (
    <PictureGlyph />
  ) : (
    <SceneGlyph />
  )

// Four bars for the Wi-Fi signal and the battery, nothing on a frame that cannot tell.
function Signal({ rssi }) {
  if (typeof rssi !== 'number') return null
  const level = rssi >= -55 ? 4 : rssi >= -65 ? 3 : rssi >= -75 ? 2 : 1
  return (
    <div className={`flex items-end gap-[${px(1)}] h-[${px(12)}]`}>
      {[4, 6, 9, 12].map((height, i) => (
        <div className={`w-[${px(3)}] h-[${px(height)}] ${i < level ? 'bg-black' : `bg-[${c.shade}]`}`} />
      ))}
    </div>
  )
}

function Battery({ percent }) {
  if (typeof percent !== 'number') return null
  return (
    <svg viewBox="0 0 10 16" className={`w-[${px(8)}] h-[${px(13)}]`}>
      <rect x="3" y="0" width="4" height="2" fill="#000000" />
      <rect x="0.5" y="1.5" width="9" height="14" fill="#ffffff" stroke="#000000" />
      <rect x="2" y={3 + (11 * (100 - Math.min(100, percent))) / 100} width="6" height={(11 * Math.min(100, percent)) / 100} fill={percent > 15 ? '#30b030' : '#d02020'} />
    </svg>
  )
}

// A running scene in the Deskbar.
const Team = ({ pressed, dim, label, onClick, className = '', children }) => (
  <Bevel pressed={pressed} className={className} inner={`items-center gap-[${px(6)}] px-[${px(6)}] h-[${px(24)}]`} onClick={onClick}>
    {children}
    <span className={`truncate min-w-0 ${dim ? `text-[${c.shade}]` : ''}`}>{label}</span>
  </Bevel>
)

// The tray: sunk into the Deskbar, with the signal, the battery and the clock.
const Tray = ({ app, now, className = '', onClick }) => (
  <Bevel className={className} inner={`items-center p-[${px(3)}]`} onClick={onClick}>
    <div className={`flex flex-1 border-t-${edge} border-l-${edge} border-[${c.shade}]`}>
      <div className={`flex flex-1 items-center gap-[${px(5)}] h-[${px(18)}] px-[${px(5)}] border-b-${edge} border-r-${edge} border-[${c.light}]`}>
        <Signal rssi={app.frame.wifiRssi} />
        <Battery percent={app.frame.batteryPercent} />
        <div className="flex-1" />
        <span className="whitespace-nowrap">{clock(now, on(app.state.twentyFourHour))}</span>
      </div>
    </div>
  </Bevel>
)

// The tab's boxes, raised a little from the yellow (from the grey on a window
// behind). Each look has its own gradient: one id is one gradient in the picture.
const BoxGradient = ({ active }) => (
  <linearGradient id={active ? 'beBoxOn' : 'beBoxOff'} gradientUnits="userSpaceOnUse" x1="0" y1="0" x2="13" y2="13">
    <stop offset="0" stopColor={(active ? c.boxes : c.idleBoxes)[0]} />
    <stop offset="1" stopColor={(active ? c.boxes : c.idleBoxes)[1]} />
  </linearGradient>
)
const boxFill = (active) => (active ? 'url(#beBoxOn)' : 'url(#beBoxOff)')
const boxLine = (active) => (active ? c.tabShade : c.idleShade)

const CloseBox = ({ active = true, onClick }) => (
  <div className={`flex p-[${px(2)}]`} onClick={onClick}>
    <svg viewBox="0 0 13 13" className={`w-[${px(13)}] h-[${px(13)}]`}>
      <BoxGradient active={active} />
      <rect x="0.5" y="0.5" width="12" height="12" fill={boxFill(active)} stroke={boxLine(active)} />
      <path d="M1.5 11V1.5H11" fill="none" stroke="#ffffff" />
    </svg>
  </div>
)

const ZoomBox = ({ active = true, onClick }) => (
  <div className={`flex p-[${px(2)}]`} onClick={onClick}>
    <svg viewBox="0 0 13 13" className={`w-[${px(13)}] h-[${px(13)}]`}>
      <BoxGradient active={active} />
      <rect x="3.5" y="3.5" width="9" height="9" fill={boxFill(active)} stroke={boxLine(active)} />
      <rect x="0.5" y="0.5" width="7" height="7" fill={boxFill(active)} stroke={boxLine(active)} />
      <path d="M1.5 6V1.5H6" fill="none" stroke="#ffffff" />
    </svg>
  </div>
)

// The scene's settings, a box like the others with a gear in it.
const GearBox = ({ active = true, onClick }) => (
  <div className={`flex p-[${px(2)}]`} onClick={onClick}>
    <svg viewBox="0 0 13 13" className={`w-[${px(13)}] h-[${px(13)}]`}>
      <BoxGradient active={active} />
      <rect x="0.5" y="0.5" width="12" height="12" fill={boxFill(active)} stroke={boxLine(active)} />
      <path d={GEAR} fill="#7a7a7a" stroke="#000000" strokeWidth="0.9" transform="translate(2 2) scale(0.5625)" />
    </svg>
  </div>
)

// The frame: grey, lit at the top left and shaded at the bottom right, around the
// scene. `frame` are its own handlers (a press on it sizes the window).
const Frame = ({ frame = {}, children }) => (
  <div className={`flex flex-col flex-1 min-h-0 border-[${edge}px] border-[${c.line}]`} {...frame}>
    <div className={`flex flex-col flex-1 min-h-0 border-t-${edge} border-l-${edge} border-[${c.light}]`}>
      <div className={`flex flex-col flex-1 min-h-0 p-[${px(3)}] border-b-${edge} border-r-${edge} border-[${c.shade}] bg-[${c.panel}]`}>
        <div className={`flex flex-col flex-1 min-h-0 border-t-${edge} border-l-${edge} border-[${c.shade}]`}>
          <div className={`flex flex-col flex-1 min-h-0 border-b-${edge} border-r-${edge} border-[${c.light}]`}>{children}</div>
        </div>
      </div>
    </div>
  </div>
)

// The tab: as wide as its title, on the top left of the frame, yellow on the window
// in front. `drag` are its own handlers (a press on it moves the window).
const Tab = ({ title, active = true, onClose, onSettings, onZoom, drag = {} }) => (
  <div className={`flex self-start max-w-full border-t-${edge} border-l-${edge} border-r-${edge} border-[${c.line}]`}>
    <div className={`flex flex-1 min-w-0 border-t-${edge} border-l-${edge} border-[${active ? c.tabLight : c.light}]`}>
      <div
        className={`flex flex-1 min-w-0 items-center h-[${px(22)}] gap-[${px(4)}] pl-[${px(2)}] pr-[${px(2)}] border-r-${edge} border-[${
          active ? c.tabShade : c.idleShade
        }] bg-[${active ? c.tab : c.idleTab}]`}
        {...drag}
      >
        <CloseBox active={active} onClick={onClose} />
        <span className={`font-bold truncate min-w-0 px-[${px(4)}]`}>{title}</span>
        {onSettings ? <GearBox active={active} onClick={onSettings} /> : null}
        <ZoomBox active={active} onClick={onZoom} />
      </div>
    </div>
  </div>
)

// The window of a frame that wraps one scene: the tab, then the frame.
const Window = ({ title, onClose, onZoom, onHide, children }) => (
  <div className="flex flex-col flex-1 min-w-0 min-h-0">
    <Tab title={title} onClose={onClose} onZoom={onZoom} drag={{ onDoubleClick: onHide }} />
    <Frame>{children}</Frame>
  </div>
)

// Tracker's icons, drawn from above and to the side as they were.
const DiskIcon = () => (
  <svg viewBox="2 4 28 24" className={`w-[${px(42)}] h-[${px(36)}]`}>
    <path d="M3 13L16 7L29 13L16 19Z" fill="#ececec" />
    <path d="M3 13L16 19V26L3 20Z" fill="#b4b4b4" />
    <path d="M16 19L29 13V20L16 26Z" fill="#8c8c8c" />
    <path d="M5.5 18.2L13.5 22" stroke="#5a5a5a" strokeWidth="1.2" />
    <path d="M21 19.2L25 17.3" stroke="#2ee05a" strokeWidth="1.6" />
    <path d="M3 13L16 7L29 13V20L16 26L3 20ZM3 13L16 19L29 13M16 19V26" fill="none" stroke="#202020" strokeWidth="0.9" strokeLinejoin="round" />
  </svg>
)

const FolderIcon = ({ children }) => (
